import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const read = path => readFile(path,'utf8');
const schemas = await Promise.all(['SCHEMA','COMMUNITY','EDITOR'].map(name=>read(`supabase/${name}.sql`)));
let sql=`-- URC only: paste in the SQL Editor of project ktfwfeuyrpvelvpdborw.
-- Generated by node scripts/prepare-setup.mjs from the reviewed source schemas.
-- Preserves existing content; no Auth users or passwords are created here.
BEGIN;
DO $urc_install$
BEGIN
 IF to_regclass('public.urc_entries') IS NULL THEN
  EXECUTE $urc_base$\n${schemas[0]}\n$urc_base$;
 END IF;
 IF to_regclass('public.urc_member_profiles') IS NULL THEN
  EXECUTE $urc_community$\n${schemas[1]}\n$urc_community$;
 END IF;
END $urc_install$;\n\n${schemas[2]}\n`;
const rows=JSON.parse(await read('public/community.json')).entries;
// UUIDv5 URL namespace gives stable seed IDs across reruns and refreshed exports.
const seedId=row=>{
 const hash=createHash('sha1').update(Buffer.from('6ba7b8119dad11d180b400c04fd430c8','hex')).update('https://powerhouse-urc.vercel.app/'+row.kind+'/'+row.slug).digest();
 hash[6]=(hash[6]&15)|80;hash[8]=(hash[8]&63)|128;
 const h=hash.subarray(0,16).toString('hex');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;
};
const ids=new Map(rows.map(row=>[row.id,seedId(row)]));
const quote=value=>"'"+value.replaceAll("'","''")+"'";
for(const row of [...rows].sort((a,b)=>Number(b.kind==='event')-Number(a.kind==='event'))){
 const payload=structuredClone(row.payload);
 if(ids.has(payload.eventId)) payload.eventId=ids.get(payload.eventId);
 if(row.kind==='event'){payload.registration='coming-soon';payload.registrationMode='free-pass';}
 const publish=!(row.kind==='album'&&!payload.eventId);
 sql+=`\nINSERT INTO public.urc_entries(id,kind,title,slug,payload,publish_requested) VALUES(${[ids.get(row.id),row.kind,row.title,row.slug].map(quote).join(',')},${quote(JSON.stringify(payload))}::jsonb,${publish}) ON CONFLICT(kind,slug) DO NOTHING;\n`;
}
sql+='\nCOMMIT;\nSELECT kind,title,slug,status FROM public.urc_entries ORDER BY kind,title;\n';
await writeFile('supabase/SETUP.sql',sql);
console.log('Prepared Supabase SETUP.sql; no remote changes made.');
